/**
 * Flow layout geometry used by the workspace view:
 *  - where the ports of a node are placed for a given orientation
 *  - the size of a node for a given orientation
 *  - how wires are routed between ports
 *  - which orientation nodes get in an 'auto' layout flow
 *
 * These functions have no dependency on the DOM or the rest of the editor.
 */
RED.viewLayout = (function() {
    // These match the node dimensions used by RED.view
    const node_width = 100;
    const node_height = 30;
    const lineCurveScale = 0.75;

    const PORT_TYPE_INPUT = 1;
    const PORT_TYPE_OUTPUT = 0;

    // Flow layout - where the ports of a node are placed
    //  - LR   : inputs on the left, outputs on the right (default)
    //  - TB   : inputs on the top, outputs on the bottom
    //  - auto : each node picks LR or TB based on the position of the nodes it is wired to
    const LAYOUT_HORIZONTAL = "LR";
    const LAYOUT_VERTICAL = "TB";
    const LAYOUT_AUTO = "auto";
    const FLOW_LAYOUTS = [LAYOUT_HORIZONTAL, LAYOUT_VERTICAL, LAYOUT_AUTO];
    // Wire style - how wires are routed between ports
    const WIRE_STYLE_CURVED = "curved";
    const WIRE_STYLE_ORTHOGONAL = "orthogonal";
    const WIRE_STYLES = [WIRE_STYLE_CURVED, WIRE_STYLE_ORTHOGONAL];
    // Distance between output ports
    const PORT_SPACING = 13;
    const PORT_SPACING_VERTICAL = 20;
    // Unit vectors for the direction a wire leaves/enters a port
    const WIRE_DIRECTIONS = { r: [1, 0], l: [-1, 0], b: [0, 1], t: [0, -1] };
    const OPPOSITE_WIRE_DIRECTION = { r: "l", l: "r", b: "t", t: "b" };

    /**
     * Generate the classic horizontal wire curve.
     * @param {number} sc 1 if the wire leaves to the right, -1 if it leaves to the left
     */
    function generateLinkPath(origX,origY, destX, destY, sc, hasStatus = false) {
        var dy = destY-origY;
        var dx = destX-origX;
        var delta = Math.sqrt(dy*dy+dx*dx);
        var scale = lineCurveScale;
        var scaleY = 0;
        if (dx*sc > 0) {
            if (delta < node_width) {
                scale = 0.75-0.75*((node_width-delta)/node_width);
                // scale += 2*(Math.min(5*node_width,Math.abs(dx))/(5*node_width));
                // if (Math.abs(dy) < 3*node_height) {
                //     scaleY = ((dy>0)?0.5:-0.5)*(((3*node_height)-Math.abs(dy))/(3*node_height))*(Math.min(node_width,Math.abs(dx))/(node_width)) ;
                // }
            }
        } else {
            scale = 0.4-0.2*(Math.max(0,(node_width-Math.min(Math.abs(dx),Math.abs(dy)))/node_width));
        }
        function genCP(cp) {
            return ` M ${cp[0]-5} ${cp[1]} h 10 M ${cp[0]} ${cp[1]-5} v 10 `
        }
        if (dx*sc > 0) {
            let cp = [
                [(origX+sc*(node_width*scale)), (origY+scaleY*node_height)],
                [(destX-sc*(scale)*node_width), (destY-scaleY*node_height)]
            ]
            return `M ${origX} ${origY} C ${cp[0][0]} ${cp[0][1]} ${cp[1][0]} ${cp[1][1]} ${destX} ${destY}`
            //    + ` ${genCP(cp[0])} ${genCP(cp[1])}`
        } else {
            let topX, topY, bottomX, bottomY
            let cp
            let midX = Math.floor(destX-dx/2);
            let midY = Math.floor(destY-dy/2);          
            if (Math.abs(dy) < 10) {
                bottomY = Math.max(origY, destY) + (hasStatus?35:25)
                let startCurveHeight = bottomY - origY
                let endCurveHeight = bottomY - destY
                cp = [
                    [ origX + sc*15 , origY ],
                    [ origX + sc*25 , origY + 5 ],
                    [ origX + sc*25 , origY + startCurveHeight/2 ],

                    [ origX + sc*25 , origY + startCurveHeight - 5 ],
                    [ origX + sc*15 , origY + startCurveHeight ],
                    [ origX , origY + startCurveHeight ],

                    [ destX - sc*15, origY + startCurveHeight ],
                    [ destX - sc*25, origY + startCurveHeight - 5 ],
                    [ destX - sc*25, destY + endCurveHeight/2 ],

                    [ destX - sc*25, destY + 5 ],
                    [ destX - sc*15, destY ],
                    [ destX, destY ],
                ]

                return "M "+origX+" "+origY+
                    " C "+
                    cp[0][0]+" "+cp[0][1]+" "+
                    cp[1][0]+" "+cp[1][1]+" "+
                    cp[2][0]+" "+cp[2][1]+" "+
                    " C " +
                    cp[3][0]+" "+cp[3][1]+" "+
                    cp[4][0]+" "+cp[4][1]+" "+
                    cp[5][0]+" "+cp[5][1]+" "+
                    " h "+dx+
                    " C "+
                    cp[6][0]+" "+cp[6][1]+" "+
                    cp[7][0]+" "+cp[7][1]+" "+
                    cp[8][0]+" "+cp[8][1]+" "+
                    " C " +
                    cp[9][0]+" "+cp[9][1]+" "+
                    cp[10][0]+" "+cp[10][1]+" "+
                    cp[11][0]+" "+cp[11][1]+" "
                // +genCP(cp[0])+genCP(cp[1])+genCP(cp[2])+genCP(cp[3])+genCP(cp[4])
                // +genCP(cp[5])+genCP(cp[6])+genCP(cp[7])+genCP(cp[8])+genCP(cp[9])+genCP(cp[10])
            } else {
                var cp_height = node_height/2;
                var y1 = (destY + midY)/2
                topX = origX + sc*node_width*scale;
                topY = dy>0?Math.min(y1 - dy/2 , origY+cp_height):Math.max(y1 - dy/2 , origY-cp_height);
                bottomX = destX - sc*node_width*scale;
                bottomY = dy>0?Math.max(y1, destY-cp_height):Math.min(y1, destY+cp_height);
                var x1 = (origX+topX)/2;
                var scy = dy>0?1:-1;
                cp = [
                    // Orig -> Top
                    [x1,origY],
                    [topX,dy>0?Math.max(origY, topY-cp_height):Math.min(origY, topY+cp_height)],
                    // Top -> Mid
                    // [Mirror previous cp]
                    [x1,dy>0?Math.min(midY, topY+cp_height):Math.max(midY, topY-cp_height)],
                    // Mid -> Bottom
                    // [Mirror previous cp]
                    [bottomX,dy>0?Math.max(midY, bottomY-cp_height):Math.min(midY, bottomY+cp_height)],
                    // Bottom -> Dest
                    // [Mirror previous cp]
                    [(destX+bottomX)/2,destY]
                ];
                if (cp[2][1] === topY+scy*cp_height) {
                    if (Math.abs(dy) < cp_height*10) {
                        cp[1][1] = topY-scy*cp_height/2;
                        cp[3][1] = bottomY-scy*cp_height/2;
                    }
                    cp[2][0] = topX;
                }
                return "M "+origX+" "+origY+
                    " C "+
                    cp[0][0]+" "+cp[0][1]+" "+
                    cp[1][0]+" "+cp[1][1]+" "+
                    topX+" "+topY+
                    " S "+
                    cp[2][0]+" "+cp[2][1]+" "+
                    midX+" "+midY+
                " S "+
                    cp[3][0]+" "+cp[3][1]+" "+
                    bottomX+" "+bottomY+
                    " S "+
                        cp[4][0]+" "+cp[4][1]+" "+
                        destX+" "+destY

                // +genCP(cp[0])+genCP(cp[1])+genCP(cp[2])+genCP(cp[3])+genCP(cp[4])
            }
        }
    }

    /**
     * Get the position of a port in workspace coordinates.
     * @param {object} n the node
     * @param {number} portType PORT_TYPE_INPUT or PORT_TYPE_OUTPUT
     * @param {number} portIndex the index of the port
     * @param {string} orientation the orientation of the node - LAYOUT_HORIZONTAL or LAYOUT_VERTICAL
     * @returns {{x:number, y:number, dir:string, box:object}} `dir` is the direction
     *          the wire leaves the port; `box` is the bounding box of the node
     */
    function getPortPosition(n, portType, portIndex, orientation) {
        const w = n.w || 0;
        const h = n.h || 0;
        const box = { x1: n.x - w / 2, y1: n.y - h / 2, x2: n.x + w / 2, y2: n.y + h / 2 };
        const numOutputs = (portType === PORT_TYPE_OUTPUT) ? (n.outputs || 1) : 1;
        portIndex = portIndex || 0;
        if (orientation === LAYOUT_VERTICAL) {
            if (portType === PORT_TYPE_OUTPUT) {
                return { x: n.x - ((numOutputs - 1) / 2) * PORT_SPACING_VERTICAL + PORT_SPACING_VERTICAL * portIndex, y: n.y + h / 2, dir: "b", box };
            }
            return { x: n.x, y: n.y - h / 2, dir: "t", box };
        }
        box.y2 += (n.statusHeight || 0);
        if (portType === PORT_TYPE_OUTPUT) {
            return { x: n.x + w / 2, y: n.y - ((numOutputs - 1) / 2) * PORT_SPACING + PORT_SPACING * portIndex, dir: "r", box };
        }
        return { x: n.x - w / 2, y: n.y, dir: "l", box };
    }

    /**
     * Get the position of the end of a wire being dragged from a port.
     */
    function getDragEndPosition(start, x, y) {
        return { x, y, dir: OPPOSITE_WIRE_DIRECTION[start.dir] };
    }

    /**
     * Generate the path for a wire between two ports.
     * @param {object} start the start port - see getPortPosition
     * @param {object} end the end port - see getPortPosition
     * @param {boolean} hasStatus whether either node is showing a status
     * @param {string} [wireStyle] the wire style. Defaults to curved
     */
    function generateWirePath(start, end, hasStatus, wireStyle) {
        wireStyle = wireStyle || WIRE_STYLE_CURVED;
        if (wireStyle === WIRE_STYLE_ORTHOGONAL) {
            return generateOrthogonalPath(start, end, hasStatus, 8);
        }
        if (start.dir === "r" && end.dir === "l") {
            return generateLinkPath(start.x, start.y, end.x, end.y, 1, hasStatus);
        } else if (start.dir === "l" && end.dir === "r") {
            return generateLinkPath(start.x, start.y, end.x, end.y, -1, hasStatus);
        } else if ((start.dir === "b" && end.dir === "t") || (start.dir === "t" && end.dir === "b")) {
            const sc = start.dir === "b" ? 1 : -1;
            if ((end.y - start.y) * sc >= 30) {
                // Wire flows downwards - reuse the horizontal curve with x/y swapped
                return transposePath(generateLinkPath(start.y, start.x, end.y, end.x, sc, false));
            }
            // Wire flows backwards - route it around the nodes
            return generateOrthogonalPath(start, end, hasStatus, 15);
        }
        return generateMixedCurvePath(start, end, hasStatus);
    }

    /**
     * Swap the x and y coordinates of an SVG path
     */
    function transposePath(path) {
        const tokens = path.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) || [];
        const result = [];
        let command = "";
        let pending = null;
        tokens.forEach(function (token) {
            if (/[a-zA-Z]/.test(token)) {
                command = token;
                result.push({ h: "v", v: "h", H: "V", V: "H" }[token] || token);
            } else if (/^[hvHV]$/.test(command)) {
                result.push(token);
            } else if (pending === null) {
                pending = token;
            } else {
                result.push(token, pending);
                pending = null;
            }
        });
        return result.join(" ");
    }

    /**
     * A bezier curve between two ports facing in perpendicular directions
     */
    function generateMixedCurvePath(start, end, hasStatus) {
        const sd = WIRE_DIRECTIONS[start.dir];
        const ed = WIRE_DIRECTIONS[end.dir];
        const vx = end.x - start.x;
        const vy = end.y - start.y;
        if (vx * sd[0] + vy * sd[1] <= 0 || -(vx * ed[0] + vy * ed[1]) <= 0) {
            // One of the ports faces away from the other end - a simple curve
            // would cut through the node, so route the wire around it
            return generateOrthogonalPath(start, end, hasStatus, 15);
        }
        const distance = Math.sqrt((end.x - start.x) * (end.x - start.x) + (end.y - start.y) * (end.y - start.y));
        const k = Math.max(20, Math.min(distance / 2, node_width * lineCurveScale));
        return `M ${start.x} ${start.y} C ${start.x + sd[0] * k} ${start.y + sd[1] * k} ${end.x + ed[0] * k} ${end.y + ed[1] * k} ${end.x} ${end.y}`;
    }

    /**
     * Calculate where a wire that has to go backwards should cross over,
     * avoiding the nodes at either end where possible.
     * @param {number} axis 0 for x, 1 for y
     */
    function getWireDetour(start, end, axis, hasStatus) {
        const margin = 20 + ((hasStatus && axis === 1) ? 10 : 0);
        const lo = axis === 0 ? "x1" : "y1";
        const hi = axis === 0 ? "x2" : "y2";
        const sb = start.box;
        const eb = end.box;
        if (sb && eb) {
            if (sb[hi] + margin <= eb[lo]) {
                return (sb[hi] + eb[lo]) / 2;
            } else if (eb[hi] + margin <= sb[lo]) {
                return (eb[hi] + sb[lo]) / 2;
            }
            return Math.max(sb[hi], eb[hi]) + margin;
        }
        const sv = axis === 0 ? start.x : start.y;
        const ev = axis === 0 ? end.x : end.y;
        const box = sb || eb;
        if (Math.abs(sv - ev) < 2 * margin) {
            return Math.max(sv, ev, box ? box[hi] : -Infinity) + margin;
        }
        return (sv + ev) / 2;
    }

    /**
     * Generate a wire made of horizontal and vertical segments with rounded corners
     */
    function generateOrthogonalPath(start, end, hasStatus, cornerRadius) {
        const stub = 15;
        const sd = WIRE_DIRECTIONS[start.dir];
        const ed = WIRE_DIRECTIONS[end.dir];
        const p1 = [start.x + sd[0] * stub, start.y + sd[1] * stub];
        const p2 = [end.x + ed[0] * stub, end.y + ed[1] * stub];
        const points = [[start.x, start.y], p1];
        const startHorizontal = sd[0] !== 0;
        const endHorizontal = ed[0] !== 0;
        // Build a point from a value on axis `a` and a value on the other axis
        const pt = (a, va, vb) => a === 0 ? [va, vb] : [vb, va];
        if (startHorizontal === endHorizontal) {
            const a = startHorizontal ? 0 : 1;
            const b = 1 - a;
            const forward = sd[a] === -ed[a] && (p2[a] - p1[a]) * sd[a] >= 0;
            if (forward) {
                const mid = (p1[a] + p2[a]) / 2;
                points.push(pt(a, mid, p1[b]), pt(a, mid, p2[b]));
            } else {
                const mid = getWireDetour(start, end, b, hasStatus);
                points.push(pt(a, p1[a], mid), pt(a, p2[a], mid));
            }
        } else {
            const corner = startHorizontal ? [p2[0], p1[1]] : [p1[0], p2[1]];
            const startOk = startHorizontal ? (corner[0] - p1[0]) * sd[0] >= 0 : (corner[1] - p1[1]) * sd[1] >= 0;
            const endOk = endHorizontal ? (p2[0] - corner[0]) * -ed[0] >= 0 : (p2[1] - corner[1]) * -ed[1] >= 0;
            if (startOk && endOk) {
                points.push(corner);
            } else {
                points.push(startHorizontal ? [p1[0], p2[1]] : [p2[0], p1[1]]);
            }
        }
        points.push(p2, [end.x, end.y]);
        return generateRoundedPolylinePath(points, cornerRadius);
    }

    function generateRoundedPolylinePath(points, radius) {
        const same = (a, b) => Math.abs(a - b) < 0.01;
        const pts = [];
        points.forEach(function (p) {
            const last = pts[pts.length - 1];
            if (!last || !same(last[0], p[0]) || !same(last[1], p[1])) {
                pts.push(p);
            }
        });
        // Remove points in the middle of a straight segment
        for (let i = pts.length - 2; i > 0; i--) {
            const a = pts[i - 1], b = pts[i], c = pts[i + 1];
            if ((same(a[0], b[0]) && same(b[0], c[0])) || (same(a[1], b[1]) && same(b[1], c[1]))) {
                pts.splice(i, 1);
            }
        }
        let path = `M ${pts[0][0]} ${pts[0][1]}`;
        for (let i = 1; i < pts.length - 1; i++) {
            const p0 = pts[i - 1], p = pts[i], p1 = pts[i + 1];
            const l0 = Math.sqrt((p[0] - p0[0]) * (p[0] - p0[0]) + (p[1] - p0[1]) * (p[1] - p0[1]));
            const l1 = Math.sqrt((p1[0] - p[0]) * (p1[0] - p[0]) + (p1[1] - p[1]) * (p1[1] - p[1]));
            const r = Math.min(radius, l0 / 2, l1 / 2);
            const ax = p[0] - (p[0] - p0[0]) / l0 * r;
            const ay = p[1] - (p[1] - p0[1]) / l0 * r;
            const bx = p[0] + (p1[0] - p[0]) / l1 * r;
            const by = p[1] + (p1[1] - p[1]) / l1 * r;
            path += ` L ${ax} ${ay} Q ${p[0]} ${p[1]} ${bx} ${by}`;
        }
        const last = pts[pts.length - 1];
        path += ` L ${last[0]} ${last[1]}`;
        return path;
    }

    /**
     * Calculate the width and height of a node
     * @param {object} n the node
     * @param {object} labelParts the result of getLabelParts for the node's label
     * @param {boolean} hideLabel whether the label is hidden
     * @param {string} orientation the node's orientation
     * @returns {number[]} [width, height]
     */
    function getNodeSize(n, labelParts, hideLabel, orientation) {
        const numOutputs = n.outputs || 0;
        let w, h;
        if (orientation === LAYOUT_VERTICAL) {
            // Outputs are spread along the bottom edge
            if (hideLabel) {
                w = Math.max(node_height, numOutputs * PORT_SPACING_VERTICAL);
                h = node_height;
            } else {
                w = Math.max(node_width, 20 * (Math.ceil((labelParts.width + 50 + (n._def.inputs > 0 ? 7 : 0)) / 20)), numOutputs * PORT_SPACING_VERTICAL);
                h = Math.max(6 + 24 * labelParts.lines.length, 30);
            }
        } else if (hideLabel) {
            w = node_height;
            h = Math.max(node_height, numOutputs * 15);
        } else {
            w = Math.max(node_width, 20 * (Math.ceil((labelParts.width + 50 + (n._def.inputs > 0 ? 7 : 0)) / 20)));
            h = Math.max(6 + 24 * labelParts.lines.length, numOutputs * 15, 30);
        }
        return [w, h];
    }

    /**
     * Work out the orientation of the nodes in an 'auto' layout flow. Each wire
     * votes on whether its ends should be vertical (the wire is mostly
     * vertical) or horizontal. Nodes with no wires are not included.
     * @param {object[]} links the wires of the flow
     * @returns {object} map of node id to LAYOUT_VERTICAL for nodes that should be vertical
     */
    function computeAutoOrientations(links) {
        const votes = {};
        const result = {};
        links.forEach(function (l) {
            if (l.link) {
                // Ignore virtual wires between link nodes
                return;
            }
            const vote = Math.abs(l.target.y - l.source.y) > Math.abs(l.target.x - l.source.x) ? 1 : -1;
            votes[l.source.id] = (votes[l.source.id] || 0) + vote;
            votes[l.target.id] = (votes[l.target.id] || 0) + vote;
        });
        for (const id in votes) {
            if (votes[id] > 0) {
                result[id] = LAYOUT_VERTICAL;
            }
        }
        return result;
    }

    /**
     * Add an option for a value that is not one of the known options of a
     * select box, so an unknown value (for example from an imported flow) is
     * shown and kept rather than silently removed when the form is applied.
     * @param {Array<{val: string, text: string}>} options the known options
     * @param {*} value the current value
     * @param {function(string): string} label returns the text of the option for the unknown value
     * @returns {Array<{val: string, text: string}>} a new list of options
     */
    function addUnknownOption(options, value, label) {
        const result = options.slice();
        if (value !== undefined && value !== null && value !== "") {
            const val = String(value);
            if (!options.some(function(o) { return o.val === val })) {
                result.push({ val: val, text: label(val) });
            }
        }
        return result;
    }

    /**
     * Get the layout properties to store with a flow (tab or subflow) when it
     * is exported or deployed, so it looks the same for other users and on
     * other instances.
     *  - a value set on the flow is kept as is (including unknown values)
     *  - a flow without its own value gets the editor default from the user
     *    settings, but only if it is a known value that differs from the
     *    default (LR / curved). Flows using the defaults are stored unchanged.
     * @param {object} flow the tab or subflow
     * @param {object} [viewSettings] the user's view settings (`editor.view`)
     * @returns {{layout?: string, wireStyle?: string}}
     */
    function getPersistedFlowOptions(flow, viewSettings) {
        const result = {};
        viewSettings = viewSettings || {};
        [
            ["layout", "view-flow-layout", FLOW_LAYOUTS, LAYOUT_HORIZONTAL],
            ["wireStyle", "view-wire-style", WIRE_STYLES, WIRE_STYLE_CURVED]
        ].forEach(function([prop, setting, values, defaultValue]) {
            if (flow && flow[prop]) {
                result[prop] = flow[prop];
            } else {
                const value = viewSettings[setting];
                if (value !== defaultValue && values.indexOf(value) !== -1) {
                    result[prop] = value;
                }
            }
        });
        return result;
    }

    return {
        PORT_TYPE_INPUT,
        PORT_TYPE_OUTPUT,
        LAYOUT_HORIZONTAL,
        LAYOUT_VERTICAL,
        LAYOUT_AUTO,
        FLOW_LAYOUTS,
        WIRE_STYLE_CURVED,
        WIRE_STYLE_ORTHOGONAL,
        WIRE_STYLES,
        PORT_SPACING,
        PORT_SPACING_VERTICAL,
        WIRE_DIRECTIONS,
        OPPOSITE_WIRE_DIRECTION,
        generateLinkPath,
        getPortPosition,
        getDragEndPosition,
        generateWirePath,
        transposePath,
        generateMixedCurvePath,
        generateOrthogonalPath,
        generateRoundedPolylinePath,
        getWireDetour,
        getNodeSize,
        computeAutoOrientations,
        addUnknownOption,
        getPersistedFlowOptions
    };
})();

// Allow CommonJS import for testing
if (typeof module !== "undefined" && module.exports) {
    module.exports = RED.viewLayout;
}
